  Future<void> _toggleSync(bool value) async {
    setState(() {
      _isSyncEnabled = value;
    });

    if (value) {
      _log("Initializing Secure P2P Engine...");
      final devName = _nameController.text.trim();

      if (Platform.isAndroid) {
        try {
          final bool? hasOverlay = await _serviceChannel.invokeMethod<bool>('checkOverlayPermission');
          if (hasOverlay != null && !hasOverlay) {
            _log("Overlay permission not granted.");
            final proceed = await _showOverlayPermissionExplainDialog();
            if (proceed) {
              await _serviceChannel.invokeMethod('requestOverlayPermission');
              _log("Opening overlay settings. Please enable display over other apps.");
            }
          }
        } catch (e) {
          _log("Overlay permission check error: $e");
        }

        try {
          final bool? ignoringBattery = await _serviceChannel.invokeMethod<bool>('checkBatteryOptimization');
          if (ignoringBattery != null && !ignoringBattery) {
            _log("Battery optimization is enabled.");
            final proceed = await _showBatteryOptimizationExplainDialog();
            if (proceed) {
              await _serviceChannel.invokeMethod('requestDisableBatteryOptimization');
              _log("Requesting to ignore battery optimizations...");
            }
          }
        } catch (e) {
          _log("Battery optimization check error: $e");
        }

        try {
          await _serviceChannel.invokeMethod('startForegroundService');
        } catch (e) {
          _log("Foreground service error: $e");
        }
      }

      // Resolve secure storage directory path
      String storageDir = "/home/sanal-sivakumar/Documents/clipboard";
      if (Platform.isLinux) {
        final home = Platform.environment['HOME'];
        storageDir = home != null ? "$home/.config/syncboard" : Directory.current.path;
      } else if (Platform.isWindows) {
        final appData = Platform.environment['APPDATA'];
        storageDir = appData != null ? "$appData/syncboard" : Directory.current.path;
      } else if (Platform.isAndroid) {
        storageDir = "/data/data/com.example.clipboard/files";
      } else if (Platform.isIOS) {
        storageDir = "${Directory.systemTemp.path}/syncboard";
      }

      await Directory(storageDir).create(recursive: true);

      String platformStr = "linux";
      if (Platform.isAndroid) {
        platformStr = "android";
      } else if (Platform.isIOS) {
        platformStr = "ios";
      } else if (Platform.isWindows) {
        platformStr = "windows";
      }

      try {
        await api.startSync(
          storageDir: storageDir,
          deviceName: devName.isEmpty ? "Secured Peer" : devName,
          platform: platformStr,
          deviceId: _deviceId,
        );
        _log("P2P server running. Local Storage: $storageDir");

        if (Platform.isAndroid) {
          _startAndroidClipboardPoller();
        } else if (Platform.isIOS) {
          try {
            await _clipboardChannel.invokeMethod('startSilentAudio');
            _log("Background silent audio started.");
          } catch (e) {
            _log("Failed to start silent audio: $e");
          }
          _startIosClipboardPoller();
        }

        _startSyncUiRefresher();
      } catch (e) {
        _log("Sync initialization failed: $e");
      }
    } else {
      _log("Shutting down P2P sync...");
      _androidClipboardTimer?.cancel();
      _iosClipboardTimer?.cancel();
      _uiRefreshTimer?.cancel();

      if (Platform.isAndroid) {
        try {
          await _serviceChannel.invokeMethod('stopForegroundService');
        } catch (e) {
          _log("Failed to stop foreground service: $e");
        }
      } else if (Platform.isIOS) {
        try {
          await _clipboardChannel.invokeMethod('stopSilentAudio');
          _log("Background silent audio stopped.");
        } catch (e) {
          _log("Failed to stop silent audio: $e");
        }
        try {
          await api.handleAppBackground();
        } catch (e) {
          _log("Failed to suspend Rust engine: $e");
        }
      }

      setState(() {
        _discoveredPeers = [];
        _trustedPeers = [];
      });
    }
  }

  void _startSyncUiRefresher() {
    _uiRefreshTimer?.cancel();
    _uiRefreshTimer = Timer.periodic(const Duration(seconds: 2), (timer) async {
      if (!_isSyncEnabled) return;
      try {
        final discList = await api.getDiscoveredPeers();
        final trustList = await api.getTrustedPeers();
        setState(() {
          _discoveredPeers = discList;
          _trustedPeers = trustList;
        });
      } catch (_) {
        // Skips updating if libraries aren't ready
      }
    });
  }

  void _startAndroidClipboardPoller() {
    _androidClipboardTimer?.cancel();
    _androidClipboardTimer = Timer.periodic(const Duration(milliseconds: 500), (timer) async {
      if (!_isSyncEnabled) return;
      try {
        final clipData = await Clipboard.getData(Clipboard.kTextPlain);
        final text = clipData?.text;

        if (text != null && text.isNotEmpty && text != _lastClipboardText) {
          _lastClipboardText = text;
          _log("Local clip changed: '${text.length > 25 ? '${text.substring(0, 25)}...' : text}'");
          
          _addClipToHistory(text, "This Device");

          try {
            await api.sendLocalClipboardUpdate(content: text);
          } catch (e) {
            _log("Clipboard broadcast error: $e");
          }
        }
      } catch (e) {
        debugPrint("Android Clipboard poll error: $e");
      }
    });
  }

  bool _isPeerTrusted(String peerId) {
    return _trustedPeers.any((tp) => tp.deviceId == peerId);
  }

  void _addClipToHistory(String text, String source) {
    if (_clipboardHistory.isNotEmpty && _clipboardHistory.first.text == text) {
      return;
    }

    ClipType type = ClipType.text;
    if (text.startsWith("http://") || text.startsWith("https://")) {
      type = ClipType.link;
    } else if (text.contains(";") || text.contains("{") || text.contains("}") || text.contains("pkg") || text.contains("npm") || text.contains("cargo") || text.contains("flutter")) {
      type = ClipType.code;
    }

    setState(() {
      _clipboardHistory.insert(
        0,
        ClipItem(
          type: type,
          text: text,
          source: source,
          timestamp: DateTime.now(),
        ),
      );
      if (_clipboardHistory.length > 10) {
        _clipboardHistory.removeLast();
      }
    });
  }

  DeviceKind _getDeviceIconKind(String name) {
    final lower = name.toLowerCase();
    if (lower.contains('linux') || lower.contains('pc') || lower.contains('desktop') || lower.contains('windows') || lower.contains('macos')) {
      return DeviceKind.desktop;
    } else if (lower.contains('android') || lower.contains('phone')) {
      return DeviceKind.phone;
    } else if (lower.contains('ipad') || lower.contains('ios') || lower.contains('client')) {
      return DeviceKind.tablet;
    }
    return DeviceKind.laptop;
  }

  List<Device> _buildPairedDeviceList() {
    return _trustedPeers.map<Device>((tp) {
      final String id = tp.deviceId;
      final String name = tp.deviceName;

      dynamic matchingDisc;
      try {
        matchingDisc = _discoveredPeers.firstWhere((dp) => dp.deviceId == id);
      } catch (_) {
        matchingDisc = null;
      }

      final bool isOnline = matchingDisc != null && matchingDisc.connectionStatus == "Connected";
      final String ip = matchingDisc?.ipAddress ?? "Offline";
      final String? tag = matchingDisc != null && matchingDisc.wsPort == 0 ? "client only" : null;

      return Device(
        id: id,
        name: name,
        ip: ip,
        kind: _getDeviceIconKind(name),
        paired: true,
        online: isOnline,
        subtitle: isOnline ? "$ip • synced $_lastSyncTimestamp" : "Offline",
        tag: tag,
      );
    }).toList();
  }

  List<Device> _buildDiscoveredDeviceList() {
    return _discoveredPeers
        .where((dp) => !_isPeerTrusted(dp.deviceId))
        .map<Device>((dp) {
      final String id = dp.deviceId;
      final String name = dp.deviceName.isEmpty ? "Unknown Device" : dp.deviceName;
      final String ip = dp.ipAddress;
      final String? tag = dp.wsPort == 0 ? "client only" : null;

      return Device(
        id: id,
        name: name,
        ip: ip,
        kind: _getDeviceIconKind(name),
        paired: false,
        online: false,
        subtitle: "$ip:${dp.wsPort} • discovered",
        tag: tag,
      );
    }).toList();
  }

  void _showUnpairConfirmation(String peerId, String name) {
    showDialog(
      context: context,
      barrierColor: Colors.black.withOpacity(.55),
      builder: (context) => Material(
        color: Colors.transparent,
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 360),
            child: Padding(
              padding: const EdgeInsets.all(20),
              child: GlassCard(
                radius: 24,
                padding: const EdgeInsets.all(24),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Container(
                          width: 42,
                          height: 42,
                          decoration: BoxDecoration(
                            color: AB.danger.withOpacity(.14),
                            borderRadius: BorderRadius.circular(12),
                            border: Border.all(color: AB.danger.withOpacity(.3)),
                          ),
                          child: const Icon(
                            Icons.link_off_rounded,
                            color: AB.danger,
                            size: 22,
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Text(
                            "Confirm Unpair",
                            style: AB.h1.copyWith(fontSize: 18),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 16),
                    Text(
                      "Are you sure you want to unpair from $name? Secure sessions will be immediately terminated.",
                      style: AB.sub.copyWith(color: AB.text2, height: 1.4, fontSize: 13.5),
                    ),
                    const SizedBox(height: 24),
                    Row(
                      mainAxisAlignment: MainAxisAlignment.end,
                      children: [
                        _DialogButton(
                          label: "Cancel",
                          onTap: () => Navigator.pop(context),
                        ),
                        const SizedBox(width: 10),
                        _DialogButton(
                          label: "Unpair",
                          primary: true,
                          danger: true,
                          onTap: () {
                            api.unpairDevice(peerId: peerId);
                            Navigator.pop(context);
                            _log("Device $name unpaired and untrusted.");
                          },
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  // Responsive UI shell components
  Widget _content({required bool compact}) {
    final Widget screen = _activeNavIndex == 0
        ? DevicesScreen(
            compact: compact,
            pairedDevices: _buildPairedDeviceList(),
            discoveredDevices: _buildDiscoveredDeviceList(),
            clipboardHistory: _clipboardHistory,
            manualIpController: _manualIpController,
            isSyncEnabled: _isSyncEnabled,
            lastSyncTimestamp: _lastSyncTimestamp,
            onPair: (device) {
              _log("Sending pairing request to ${device.name}...");
              api.initiatePairing(peerId: device.id);
            },
            onUnpair: (device) {
              _showUnpairConfirmation(device.id, device.name);
            },
            onManualConnect: () {
              final ip = _manualIpController.text.trim();
              if (ip.isEmpty) return;
              _log("Initiating manual pairing to $ip...");
              api.initiatePairingToIp(ipOrAddr: ip);
            },
          )
        : SettingsScreen(
            compact: compact,
            nameController: _nameController,
            isSyncEnabled: _isSyncEnabled,
            onSyncToggle: _toggleSync,
            localIp: _localIp,
            deviceId: _deviceId,
            lastSyncTimestamp: _lastSyncTimestamp,
            myFingerprint: _myFingerprint,
            logs: _logs,
            onClearLogs: () {
              setState(() {
                _logs.clear();
              });
            },
          );

    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 350),
      switchInCurve: AB.ease,
      transitionBuilder: (child, anim) => FadeTransition(
        opacity: anim,
        child: SlideTransition(
          position: Tween(begin: const Offset(0, .03), end: Offset.zero).animate(anim),
          child: child,
        ),
      ),
      child: KeyedSubtree(key: ValueKey(_activeNavIndex), child: screen),
    );
  }

