class _DialogButton extends StatelessWidget {
  final String label;
  final VoidCallback onTap;
  final bool primary;
  final bool danger;

  const _DialogButton({
    required this.label,
    required this.onTap,
    this.primary = false,
    this.danger = false,
  });

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(AB.rSm),
          gradient: primary
              ? (danger
                  ? const LinearGradient(colors: [AB.danger, Color(0xFFEF4444)])
                  : AB.accentGrad)
              : null,
          color: primary ? null : AB.glassStrong,
          border: primary ? null : Border.all(color: AB.stroke),
          boxShadow: primary
              ? [
                  BoxShadow(
                    color: (danger ? AB.danger : AB.accent).withOpacity(.3),
                    blurRadius: 16,
                    spreadRadius: -4,
                  )
                ]
              : null,
        ),
        child: Text(
          label,
          style: AB.body.copyWith(
            color: primary ? (danger ? Colors.white : const Color(0xFF060B27)) : AB.text,
            fontWeight: FontWeight.w600,
          ),
        ),
      ),
    );
  }
}
